package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.MathArrays;
import org.apache.commons.math3.util.Pair;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link DiscreteDistribution#getSamples()}.
 */
public class DiscreteDistribution_getSamples_TriageGen2Test {

    @Test
    public void testGetSamplesWithMultipleElements() throws Exception {
        // Arrange
        List<Pair<String, Double>> inputSamples = new ArrayList<>();
        inputSamples.add(new Pair<>("A", 0.2));
        inputSamples.add(new Pair<>("B", 0.5));
        inputSamples.add(new Pair<>("C", 0.3));

        DiscreteDistribution<String> distribution = new DiscreteDistribution<>(inputSamples);

        // Act
        List<Pair<String, Double>> result = distribution.getSamples();

        // Assert
        assertNotNull(result);
        assertEquals(3, result.size());

        assertEquals("A", result.get(0).getFirst());
        assertEquals(0.2, result.get(0).getSecond(), 1e-10);

        assertEquals("B", result.get(1).getFirst());
        assertEquals(0.5, result.get(1).getSecond(), 1e-10);

        assertEquals("C", result.get(2).getFirst());
        assertEquals(0.3, result.get(2).getSecond(), 1e-10);
    }

    @Test
    public void testGetSamplesWithSingleElement() throws Exception {
        // Arrange
        List<Pair<Integer, Double>> inputSamples = new ArrayList<>();
        inputSamples.add(new Pair<>(1, 1.0));

        DiscreteDistribution<Integer> distribution = new DiscreteDistribution<>(inputSamples);

        // Act
        List<Pair<Integer, Double>> result = distribution.getSamples();

        // Assert
        assertNotNull(result);
        assertEquals(1, result.size());
        assertEquals(Integer.valueOf(1), result.get(0).getFirst());
        assertEquals(1.0, result.get(0).getSecond(), 1e-10);
    }

    @Test
    public void testGetSamplesWithEmptyList() throws Exception {
        // Arrange
        List<Pair<Double, Double>> inputSamples = new ArrayList<>();
        DiscreteDistribution<Double> distribution = new DiscreteDistribution<>(inputSamples);

        // Act
        List<Pair<Double, Double>> result = distribution.getSamples();

        // Assert
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testGetSamplesIntegrity() throws Exception {
        // Testing that the returned list is a new list object (shallow copy of pairs)
        // Arrange
        List<Pair<String, Double>> inputSamples = Arrays.asList(
            new Pair<>("X", 1.0)
        );
        DiscreteDistribution<String> distribution = new DiscreteDistribution<>(inputSamples);

        // Act
        List<Pair<String, Double>> result1 = distribution.getSamples();
        List<Pair<String, Double>> result2 = distribution.getSamples();

        // Assert
        assertNotNull(result1);
        assertNotNull(result2);
        assertEquals(result1.size(), result2.size());
        assertEquals(result1.get(0).getFirst(), result2.get(0).getFirst());
        assertEquals(result1.get(0).getSecond(), result2.get(0).getSecond(), 1e-10);
    }
}
